# ② 滑动窗口：最长无重复字符子串 O(N)
def longest_unique(s):
    seen, left, best = {}, 0, 0
    for right, ch in enumerate(s):
        if ch in seen and seen[ch] >= left:
            left = seen[ch] + 1        # 左边界跳过重复
        seen[ch] = right
        best = max(best, right - left + 1)
    return best

# ③ 动态规划：编辑距离（diff 工具的内核）
def edit_distance(a, b):
    dp = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(len(a) + 1):
        dp[i][0] = i
    for j in range(len(b) + 1):
        dp[0][j] = j
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]           # 相同: 免费
            else:
                dp[i][j] = 1 + min(dp[i-1][j],     # 删
                                   dp[i][j-1],     # 增
                                   dp[i-1][j-1])   # 改
    return dp[-1][-1]

from abc import ABC, abstractmethod

# 抽象：高层业务只认识这个接口（DIP）
class LLMProvider(ABC):
    @abstractmethod
    def chat(self, messages: list, **kw) -> str: ...

class OpenAIProvider(LLMProvider):
    def chat(self, messages, **kw):
        return call_openai(messages, **kw)

class DeepSeekProvider(LLMProvider):
    def chat(self, messages, **kw):
        return call_deepseek(messages, **kw)

# 高层业务：不 import 任何具体供应商
class QAService:
    def __init__(self, provider: LLMProvider):   # 构造器注入
        self.provider = provider
    def ask(self, q: str) -> str:
        return self.provider.chat([{'role': 'user', 'content': q}])

# 装配时决定实现（改一行 = 换供应商）
