# ② 装饰器：重试横切关注点，不污染业务
def retry(times=3):
    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*a, **kw):
            for i in range(times):
                try:
                    return fn(*a, **kw)
                except Exception:
                    if i == times - 1:
                        raise
                    time.sleep(2 ** i)
        return wrapper
    return deco

# ③ 观察者：埋点与业务解耦
LISTENERS = []
def on_event(fn):
    LISTENERS.append(fn)
    return fn

def emit(event, payload):
    for fn in LISTENERS:
        fn(event, payload)

@on_event
def log_usage(event, payload):
    print(f'[日志] {event}: {payload}')
